import SwiftUI

@available(macOS, unavailable)
@MainActor
public protocol FLXOneTimeCodeFieldStyle {
    associatedtype Body: View
    typealias Configuration = FLXOneTimeCodeFieldStyleConfiguration

    @ViewBuilder func makeBody(configuration: Configuration) -> Body
}

// A style draws the slots however it likes. Taps pick a slot by its share of
// the field's width, so lay the slots out evenly across the field.
@available(macOS, unavailable)
public struct FLXOneTimeCodeFieldStyleConfiguration {
    public struct Slot: Identifiable {
        public let id: Int
        public let character: Text?
        // The slot the next digit goes into, or the one it replaces.
        public let isActive: Bool
    }

    public let slots: [Slot]
    public let isFocused: Bool
}

// `groupSize` splits the slots into groups with a dash between them, such as
// 3 + 3 for a six-digit code.
@available(macOS, unavailable)
public struct FLXDefaultOneTimeCodeFieldStyle: FLXOneTimeCodeFieldStyle {
    private let groupSize: Int?

    public init(groupSize: Int? = nil) {
        self.groupSize = groupSize
    }

    public func makeBody(configuration: Configuration) -> some View {
        FLXOneTimeCodeFieldStyleBody(configuration: configuration, groupSize: groupSize)
    }
}

@available(macOS, unavailable)
struct AnyFLXOneTimeCodeFieldStyle: FLXOneTimeCodeFieldStyle {
    private let _makeBody: (Configuration) -> AnyView

    init<S: FLXOneTimeCodeFieldStyle>(_ style: S) {
        _makeBody = { AnyView(style.makeBody(configuration: $0)) }
    }

    func makeBody(configuration: Configuration) -> AnyView {
        _makeBody(configuration)
    }
}

@available(macOS, unavailable)
private struct FLXOneTimeCodeFieldStyleKey: EnvironmentKey {
    static let defaultValue: AnyFLXOneTimeCodeFieldStyle? = nil
}

@available(macOS, unavailable)
extension EnvironmentValues {
    var flxOneTimeCodeFieldStyle: AnyFLXOneTimeCodeFieldStyle? {
        get { self[FLXOneTimeCodeFieldStyleKey.self] }
        set { self[FLXOneTimeCodeFieldStyleKey.self] = newValue }
    }
}

@available(macOS, unavailable)
extension View {
    public func flxOneTimeCodeFieldStyle<S: FLXOneTimeCodeFieldStyle>(_ style: S) -> some View {
        environment(\.flxOneTimeCodeFieldStyle, AnyFLXOneTimeCodeFieldStyle(style))
    }
}

private enum FLXOneTimeCodeFieldMetrics {
    // The slot grows with the text until the row would outgrow the field, then
    // stops: six slots at the largest accessibility size need about 660pt.
    static let slotWidth: CGFloat = 44
    static let slotAspectRatio: CGFloat = 44.0 / 52.0
    static let largestDigitSize: DynamicTypeSize = .xxxLarge
    static let caretWidth: CGFloat = 2
    static let caretHeightRatio: CGFloat = 0.45
    static let caretBlink: Double = 0.5
}

@available(macOS, unavailable)
private struct FLXOneTimeCodeFieldStyleBody: View {
    @Environment(\.flxTheme) private var theme
    @Environment(\.isEnabled) private var isEnabled
    @ScaledMetric(relativeTo: .title2) private var slotWidth = FLXOneTimeCodeFieldMetrics.slotWidth

    let configuration: FLXOneTimeCodeFieldStyleConfiguration
    let groupSize: Int?

    var body: some View {
        HStack(spacing: FLXSpacing.sm) {
            ForEach(groups, id: \.first?.id) { group in
                if group.first?.id != 0 {
                    separator
                }
                HStack(spacing: FLXSpacing.sm) {
                    ForEach(group) { slot in
                        slotView(slot)
                    }
                }
            }
        }
        .opacity(opacity)
    }

    private var groups: [[FLXOneTimeCodeFieldStyleConfiguration.Slot]] {
        guard let groupSize, groupSize > 0 else { return [configuration.slots] }
        return stride(from: 0, to: configuration.slots.count, by: groupSize).map { start in
            Array(configuration.slots[start..<min(start + groupSize, configuration.slots.count)])
        }
    }

    private var separator: some View {
        Image(systemName: "minus")
            .flxFont(.body)
            .foregroundStyle(theme.colors.mutedForeground)
    }

    private func slotView(_ slot: FLXOneTimeCodeFieldStyleConfiguration.Slot) -> some View {
        RoundedRectangle(cornerRadius: theme.radius.md)
            .fill(theme.colors.card)
            .overlay {
                RoundedRectangle(cornerRadius: theme.radius.md)
                    .strokeBorder(borderColor(slot), lineWidth: borderWidth(slot))
            }
            .overlay {
                slotContent(slot)
            }
            .aspectRatio(FLXOneTimeCodeFieldMetrics.slotAspectRatio, contentMode: .fit)
            .frame(maxWidth: slotWidth)
    }

    @ViewBuilder
    private func slotContent(_ slot: FLXOneTimeCodeFieldStyleConfiguration.Slot) -> some View {
        if let character = slot.character {
            character
                .flxFont(.title2)
                .monospacedDigit()
                .foregroundStyle(theme.colors.foreground)
                .dynamicTypeSize(...FLXOneTimeCodeFieldMetrics.largestDigitSize)
                .minimumScaleFactor(0.5)
        } else if slot.isActive {
            FLXOneTimeCodeFieldCaret()
        }
    }

    private func borderColor(_ slot: FLXOneTimeCodeFieldStyleConfiguration.Slot) -> Color {
        if slot.isActive { return theme.colors.ring }
        return theme.colors.input
    }

    private func borderWidth(_ slot: FLXOneTimeCodeFieldStyleConfiguration.Slot) -> CGFloat {
        if slot.isActive { return FLXBorderWidth.thick }
        return FLXBorderWidth.thin
    }

    private var opacity: Double {
        if isEnabled { return 1 }
        return FLXOpacity.disabled
    }
}

// The real caret belongs to the hidden field, so the empty active slot draws
// its own. It stays still with Reduce Motion on.
@available(macOS, unavailable)
private struct FLXOneTimeCodeFieldCaret: View {
    @Environment(\.flxTheme) private var theme
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var isVisible = true

    var body: some View {
        GeometryReader { proxy in
            Rectangle()
                .fill(theme.colors.foreground)
                .frame(
                    width: FLXOneTimeCodeFieldMetrics.caretWidth,
                    height: proxy.size.height * FLXOneTimeCodeFieldMetrics.caretHeightRatio
                )
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
        .opacity(caretOpacity)
        .onAppear {
            guard !reduceMotion else { return }
            withAnimation(.easeInOut(duration: FLXOneTimeCodeFieldMetrics.caretBlink).repeatForever()) {
                isVisible = false
            }
        }
    }

    private var caretOpacity: Double {
        if isVisible { return 1 }
        return 0
    }
}

#if os(iOS)
import SwiftUI
import UIKit

// The field the code is typed into. It sits over the slots with clear text,
// so it gets the system keyboard, AutoFill, paste and VoiceOver while the
// style draws what people see. A SwiftUI TextField can't do this: it moves
// the caret to the start on a tap and offers Select and Select All over
// slots that hide the text.
struct FLXOneTimeCodeInput: UIViewRepresentable {
    let title: String
    @Binding var text: String
    let length: Int
    @Binding var activeIndex: Int?

    func makeUIView(context: Context) -> FLXOneTimeCodeTextField {
        let field = FLXOneTimeCodeTextField()
        field.textContentType = .oneTimeCode
        field.keyboardType = .numberPad
        field.autocorrectionType = .no
        field.spellCheckingType = .no
        field.textColor = .clear
        field.tintColor = .clear
        field.delegate = context.coordinator
        field.addTarget(context.coordinator, action: #selector(Coordinator.textChanged(_:)), for: .editingChanged)
        return field
    }

    func updateUIView(_ field: FLXOneTimeCodeTextField, context: Context) {
        context.coordinator.parent = self
        field.length = length
        field.accessibilityLabel = title
        field.isEnabled = context.environment.isEnabled
        let code = FLXOneTimeCodeInput.digits(in: text, length: length)
        if field.text != code {
            field.text = code
        }
        if text != code {
            DispatchQueue.main.async {
                text = code
            }
        }
    }

    func makeCoordinator() -> Coordinator {
        Coordinator(parent: self)
    }

    static func digits(in string: String, length: Int) -> String {
        String(string.filter(\.isWholeNumber).filter(\.isASCII).prefix(length))
    }

    final class Coordinator: NSObject, UITextFieldDelegate {
        var parent: FLXOneTimeCodeInput

        init(parent: FLXOneTimeCodeInput) {
            self.parent = parent
        }

        // Typing over a filled slot replaces its digit instead of pushing the
        // rest along, and a whole code (pasted, or filled from Messages, Mail
        // or a password app) replaces everything. Deleting keeps the default:
        // the digits after it move back one slot.
        func textField(_ textField: UITextField, shouldChangeCharactersIn range: NSRange, replacementString string: String) -> Bool {
            if string.isEmpty { return true }
            let length = parent.length
            let digits = Array(FLXOneTimeCodeInput.digits(in: string, length: length))
            if digits.isEmpty { return false }
            if digits.count == length {
                textField.text = String(digits)
                textChanged(textField)
                return false
            }
            var characters = Array(textField.text ?? "")
            let start = min(range.location, characters.count)
            let replaced = max(range.length, min(digits.count, characters.count - start))
            characters.replaceSubrange(start..<start + replaced, with: digits)
            textField.text = String(characters.prefix(length))
            textChanged(textField)
            let caret = min(start + digits.count, textField.text?.count ?? 0)
            if let position = textField.position(from: textField.beginningOfDocument, offset: caret) {
                textField.selectedTextRange = textField.textRange(from: position, to: position)
            }
            return false
        }

        @objc func textChanged(_ textField: UITextField) {
            let code = FLXOneTimeCodeInput.digits(in: textField.text ?? "", length: parent.length)
            if textField.text != code {
                textField.text = code
            }
            if parent.text != code {
                parent.text = code
            }
            reportActiveIndex(textField)
        }

        func textFieldDidChangeSelection(_ textField: UITextField) {
            reportActiveIndex(textField)
        }

        func textFieldDidBeginEditing(_ textField: UITextField) {
            reportActiveIndex(textField)
        }

        func textFieldDidEndEditing(_ textField: UITextField) {
            parent.activeIndex = nil
        }

        private func reportActiveIndex(_ textField: UITextField) {
            guard textField.isFirstResponder, let range = textField.selectedTextRange else { return }
            let offset = textField.offset(from: textField.beginningOfDocument, to: range.start)
            let index = min(offset, parent.length - 1)
            if parent.activeIndex != index {
                parent.activeIndex = index
            }
        }
    }
}

// A tap picks the slot under the finger: a filled slot gets selected so the
// next digit replaces it, and an empty one puts the caret after the last
// digit, since the code can't have gaps. The real caret, selection handles
// and the edit menu stay hidden; the style draws the active slot instead,
// and paste is the only action left (the system adds AutoFill next to it).
final class FLXOneTimeCodeTextField: UITextField {
    var length = 1

    override init(frame: CGRect) {
        super.init(frame: frame)
        addGestureRecognizer(UITapGestureRecognizer(target: self, action: #selector(tapped(_:))))
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    @objc private func tapped(_ recognizer: UITapGestureRecognizer) {
        guard isEnabled else { return }
        if !isFirstResponder {
            becomeFirstResponder()
        }
        let position = closestPosition(to: recognizer.location(in: self)) ?? endOfDocument
        selectedTextRange = textRange(from: position, to: position)
    }

    override func closestPosition(to point: CGPoint) -> UITextPosition? {
        let count = text?.count ?? 0
        let slotWidth = bounds.width / CGFloat(length)
        guard slotWidth > 0 else { return endOfDocument }
        let slot = Int(point.x / slotWidth)
        return position(from: beginningOfDocument, offset: max(0, min(slot, count)))
    }

    override var selectedTextRange: UITextRange? {
        get { super.selectedTextRange }
        set {
            guard let newValue, newValue.isEmpty else {
                super.selectedTextRange = newValue
                return
            }
            let offset = self.offset(from: beginningOfDocument, to: newValue.start)
            guard offset < text?.count ?? 0,
                  let start = position(from: beginningOfDocument, offset: offset),
                  let end = position(from: start, offset: 1) else {
                super.selectedTextRange = newValue
                return
            }
            super.selectedTextRange = textRange(from: start, to: end)
        }
    }

    // VoiceOver reads the code digit by digit ("four, eight, two") instead of
    // as a number, and says how much of it is filled in.
    override var accessibilityAttributedValue: NSAttributedString? {
        get { NSAttributedString(string: text ?? "", attributes: [.accessibilitySpeechSpellOut: true]) }
        set {}
    }

    override var accessibilityHint: String? {
        get {
            let entered = text?.count ?? 0
            return String(localized: "\(entered) of \(length) digits entered.")
        }
        set {}
    }

    override func caretRect(for position: UITextPosition) -> CGRect {
        .zero
    }

    override func selectionRects(for range: UITextRange) -> [UITextSelectionRect] {
        []
    }

    override func canPerformAction(_ action: Selector, withSender sender: Any?) -> Bool {
        action == #selector(paste(_:))
    }
}
#endif

import SwiftUI

// A one-time code field types into a native text field nobody sees. AutoFill
// only offers a code from Messages, Mail or a password app to a real text
// field on the system keyboard, so the slots are drawn over that one field
// instead of being fields of their own: one field per slot also breaks
// AutoFill, which pastes the whole code into a single field.
//
// The title isn't shown. It's the name VoiceOver reads for the field, so it's
// a LocalizedStringResource (or a String shown as is): UIKit's accessibility
// label needs a String, and a LocalizedStringKey can't be read back as one.
//
// The code accepts digits only. Spaces and dashes in a pasted or filled code
// are dropped, and the code never grows past `length`. React to a complete
// code with `.onChange(of:)`: the number pad has no Return key.
@available(macOS, unavailable)
public struct FLXOneTimeCodeField: View {
    @Environment(\.flxOneTimeCodeFieldStyle) private var style
    @State private var activeIndex: Int?

    @Binding private var text: String
    private let title: String
    private let length: Int

    public init(_ titleResource: LocalizedStringResource, text: Binding<String>, length: Int = 6) {
        self.init(title: String(localized: titleResource), text: text, length: length)
    }

    @_disfavoredOverload
    public init<S: StringProtocol>(_ title: S, text: Binding<String>, length: Int = 6) {
        self.init(title: String(title), text: text, length: length)
    }

    private init(title: String, text: Binding<String>, length: Int) {
        self.title = title
        self._text = text
        self.length = max(1, length)
    }

    public var body: some View {
        (style ?? AnyFLXOneTimeCodeFieldStyle(FLXDefaultOneTimeCodeFieldStyle()))
            .makeBody(configuration: configuration)
            .accessibilityHidden(true)
            .overlay {
                input
            }
    }

    @ViewBuilder
    private var input: some View {
        #if os(iOS)
        FLXOneTimeCodeInput(title: title, text: $text, length: length, activeIndex: $activeIndex)
        #endif
    }

    private var configuration: FLXOneTimeCodeFieldStyleConfiguration {
        let characters = Array(text.prefix(length))
        let slots = (0..<length).map { index in
            FLXOneTimeCodeFieldStyleConfiguration.Slot(
                id: index,
                character: character(at: index, in: characters),
                isActive: index == activeIndex
            )
        }
        return FLXOneTimeCodeFieldStyleConfiguration(slots: slots, isFocused: activeIndex != nil)
    }

    private func character(at index: Int, in characters: [Character]) -> Text? {
        guard index < characters.count else { return nil }
        return Text(verbatim: String(characters[index]))
    }
}
